#include <bits/stdc++.h>
using namespace std;

int main() {
    string input_str;
    cin >> input_str;
    string intermediate = "";
    for (size_t index = 0; index < input_str.size(); ++index) {
        if (input_str[index] == 'd' && index + 2 < input_str.size() && input_str[index+1] == 'o' && input_str[index+2] == 't') {
            intermediate += '.';
            index += 2;
        } else if (input_str[index] == 'a' && index + 1 < input_str.size() && input_str[index+1] == 't') {
            intermediate += '@';
            ++index;
        } else {
            intermediate += input_str[index];
        }
    }
    string output_final;
    if (!intermediate.empty()) {
        if (intermediate[0] == '.') output_final += "dot";
        else if (intermediate[0] == '@') output_final += "at";
        else output_final += intermediate[0];

        int at_occurrence = 0;
        for (size_t m = 1; m + 1 < intermediate.size(); ++m) {
            if (intermediate[m] == '@' && at_occurrence == 0) {
                output_final += intermediate[m];
                at_occurrence = 1;
            } else if (intermediate[m] == '@' && at_occurrence == 1) {
                output_final += "at";
            } else {
                output_final += intermediate[m];
            }
        }
        if (intermediate.back() == '.') output_final += "dot";
        else if (intermediate.back() == '@') output_final += "at";
        else output_final += intermediate.back();
    }
    cout << output_final << "\n";
}
